import unittest
from candidate import parse_music

class TestParseMusic(unittest.TestCase):
    def test_normal_case_whole_note(self):
        self.assertEqual(parse_music('o'), [4])

    def test_normal_case_half_note(self):
        self.assertEqual(parse_music('o|'), [2])

    def test_normal_case_quarter_note(self):
        self.assertEqual(parse_music('.|'), [1])

    def test_multiple_notes_separated(self):
        self.assertEqual(parse_music('o o| .| o| o| .| .| .| .| o o'), [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4])

    def test_empty_string(self):
        self.assertEqual(parse_music(''), [])

    def test_single_space(self):
        self.assertEqual(parse_music(' '), [])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            parse_music(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            parse_music(123)

    def test_invalid_note_format(self):
        with self.assertRaises(ValueError):
            parse_music('invalid')

    def test_multiple_invalid_notes(self):
        self.assertEqual(parse_music('o invalid .|'), [4, 1])

    def test_whitespace_only(self):
        self.assertEqual(parse_music('   '), [])

    def test_leading_trailing_spaces(self):
        self.assertEqual(parse_music(' o o| .| '), [4, 2, 1])

    def test_duplicate_notes(self):
        self.assertEqual(parse_music('o o o| .| .|'), [4, 4, 2, 1, 1])

    def test_mixed_case_sensitivity(self):
        self.assertEqual(parse_music('O o| .|'), [4, 2, 1])

    def test_extra_whitespace(self):
        self.assertEqual(parse_music('o   o|   .|'), [4, 2, 1])
